     5	/// This is a superset of terminal cursor styles since the renderer supports
     6	/// some additional cursor states such as the hollow block.
     7	pub const Style = enum {
     8	    // Typical cursor input styles
     9	    block,
    10	    block_hollow,
    11	    bar,
    12	    underline,
    13	
    14	    // Special cursor styles
    15	    lock,
