    17	    /// Create a cursor style from the terminal style request.
    18	    pub fn fromTerminal(term: terminal.CursorStyle) Style {
    19	        return switch (term) {
    20	            .bar => .bar,
    21	            .block => .block,
    22	            .block_hollow => .block_hollow,
    23	            .underline => .underline,
    24	        };
    25	    }
    26	};
